23	
24	    private final String appendSeparator;
25	    private final Map<String, String> results;
26	    private final Map<String, String> simpleResults;
27	    private final Map<String, ReferenceResult> referenceResults;
28	    private final Map<String, AppendResult> appendResults;
29	    private int implicitAppendOrder = -1000;
30	    private final int maxMatches;
31	    private final int maxResults;
32	    private final int appendCount;
33	    private final int referenceCount;
34	    private final int simpleCount;
35	    private int matches = 0;
