37	    DissectMatch(String appendSeparator, int maxMatches, int maxResults, int appendCount, int referenceCount) {
38	        if (maxMatches <= 0 || maxResults <= 0) {
39	            throw new IllegalArgumentException("Expected results are zero, can not construct DissectMatch");// should never happen
40	        }
41	        this.maxMatches = maxMatches;
42	        this.maxResults = maxResults;
43	        this.appendCount = appendCount;
44	        this.referenceCount = referenceCount;
45	        this.appendSeparator = appendSeparator;
46	        results = new HashMap<>(maxResults);
47	        this.simpleCount = maxMatches - referenceCount - appendCount;
48	        simpleResults = simpleCount <= 0 ? null : new HashMap<>(simpleCount);
49	        referenceResults = referenceCount <= 0 ? null : new HashMap<>(referenceCount);
50	        appendResults = appendCount <= 0 ? null : new HashMap<>(appendCount);
51	    }
52	
53	    /**
54	     * Add the key/value that was found as result of the parsing
55	     * @param key the {@link DissectKey}
56	     * @param value the discovered value for the key
57	     */
58	    void add(DissectKey key, String value) {
59	        matches++;
60	        if (key.skip()) {
61	            return;
