60	     * conversions to String. The provided char[] is not modified by this method, so
61	     * the caller needs to take care of clearing the value if it is sensitive.
62	     */
63	    public static byte[] toUtf8Bytes(char[] chars) {
64	        final CharBuffer charBuffer = CharBuffer.wrap(chars);
65	        final ByteBuffer byteBuffer = StandardCharsets.UTF_8.encode(charBuffer);
66	        final byte[] bytes;
67	        if (byteBuffer.hasArray()) {
68	            // there is no guarantee that the byte buffers backing array is the right size
69	            // so we need to make a copy
70	            bytes = Arrays.copyOfRange(byteBuffer.array(), byteBuffer.position(), byteBuffer.limit());
71	            Arrays.fill(byteBuffer.array(), (byte) 0); // clear sensitive data
72	        } else {
73	            final int length = byteBuffer.limit() - byteBuffer.position();
74	            bytes = new byte[length];
75	            byteBuffer.get(bytes);
76	            // if the buffer is not read only we can reset and fill with 0's
77	            if (byteBuffer.isReadOnly() == false) {
78	                byteBuffer.clear(); // reset
79	                for (int i = 0; i < byteBuffer.limit(); i++) {
80	                    byteBuffer.put((byte) 0);
81	                }
82	            }
83	        }
84	        return bytes;
85	    }
86	
87	    /**
88	     * Tests if a char[] contains a sequence of characters that match the prefix. This is like
89	     * {@link String#startsWith(String)} but does not require conversion of the char[] to a string.
90	     */
91	    public static boolean charsBeginsWith(String prefix, char[] chars) {
92	        if (chars == null || prefix == null) {
93	            return false;
94	        }
95	
96	        if (prefix.length() > chars.length) {
97	            return false;
98	        }
99	
100	        for (int i = 0; i < prefix.length(); i++) {
101	            if (chars[i] != prefix.charAt(i)) {
102	                return false;
103	            }
104	        }
105	
106	        return true;
107	    }
108	
109	    /**
110	     * Constant time equality check of char arrays to avoid potential timing attacks.
111	     */
112	    public static boolean constantTimeEquals(char[] a, char[] b) {
113	        Objects.requireNonNull(a, "char arrays must not be null for constantTimeEquals");
114	        Objects.requireNonNull(b, "char arrays must not be null for constantTimeEquals");
115	        if (a.length != b.length) {
116	            return false;
117	        }
118	
119	        int equals = 0;
120	        for (int i = 0; i < a.length; i++) {
121	            equals |= a[i] ^ b[i];
122	        }
123	
124	        return equals == 0;
125	    }
126	
127	    /**
128	     * Constant time equality check of strings to avoid potential timing attacks.
129	     */
130	    public static boolean constantTimeEquals(String a, String b) {
131	        Objects.requireNonNull(a, "strings must not be null for constantTimeEquals");
132	        Objects.requireNonNull(b, "strings must not be null for constantTimeEquals");
133	        if (a.length() != b.length()) {
134	            return false;
135	        }
136	
137	        int equals = 0;
138	        for (int i = 0; i < a.length(); i++) {
139	            equals |= a.charAt(i) ^ b.charAt(i);
140	        }
141	
142	        return equals == 0;
143	    }
144	}
