10	package org.elasticsearch.geometry.utils;
11	
12	import org.elasticsearch.geometry.Circle;
13	import org.elasticsearch.geometry.Geometry;
14	import org.elasticsearch.geometry.GeometryCollection;
15	import org.elasticsearch.geometry.GeometryVisitor;
16	import org.elasticsearch.geometry.Line;
17	import org.elasticsearch.geometry.LinearRing;
18	import org.elasticsearch.geometry.MultiLine;
19	import org.elasticsearch.geometry.MultiPoint;
20	import org.elasticsearch.geometry.MultiPolygon;
21	import org.elasticsearch.geometry.Point;
22	import org.elasticsearch.geometry.Polygon;
23	import org.elasticsearch.geometry.Rectangle;
24	import org.elasticsearch.geometry.ShapeType;
25	
26	import java.io.ByteArrayOutputStream;
27	import java.io.IOException;
28	import java.io.UncheckedIOException;
29	import java.nio.ByteBuffer;
30	import java.nio.ByteOrder;
31	import java.util.ArrayList;
32	import java.util.Collections;
33	import java.util.List;
34	
35	/**
36	 * Utility class for converting {@link Geometry} to and from WKB
37	 */
38	public class WellKnownBinary {
39	
40	    private WellKnownBinary() {}
41	
42	    /**
43	     * Converts the given {@link Geometry} to WKB with the provided {@link ByteOrder}
44	     */
45	    public static byte[] toWKB(Geometry geometry, ByteOrder byteOrder) {
46	        try (ByteArrayOutputStream outputStream = new ByteArrayOutputStream()) {
47	            toWKB(geometry, outputStream, ByteBuffer.allocate(8).order(byteOrder));
48	            return outputStream.toByteArray();
49	        } catch (IOException ioe) {
50	            // Should never happen as the only method throwing IOException is ByteArrayOutputStream#close and it is a NOOP
51	            throw new UncheckedIOException(ioe);
52	        }
53	    }
54	
55	    private static void toWKB(Geometry geometry, ByteArrayOutputStream out, ByteBuffer scratch) {
56	        out.write(scratch.order() == ByteOrder.BIG_ENDIAN ? 0 : 1);
57	        geometry.visit(new GeometryVisitor<Void, RuntimeException>() {
58	            @Override
59	            public Void visit(Point point) {
60	                if (point.isEmpty()) {
61	                    throw new IllegalArgumentException("Empty " + point.type() + " cannot be represented in WKB");
62	                }
63	                writeInt(out, scratch, point.hasZ() ? 1001 : 1);
64	                writeDouble(out, scratch, point.getX());
65	                writeDouble(out, scratch, point.getY());
66	                if (point.hasZ()) {
67	                    writeDouble(out, scratch, point.getZ());
68	                }
69	                return null;
70	            }
71	
72	            @Override
73	            public Void visit(Line line) {
74	                writeInt(out, scratch, line.hasZ() ? 1002 : 2);
75	                writeInt(out, scratch, line.length());
76	                for (int i = 0; i < line.length(); ++i) {
77	                    writeDouble(out, scratch, line.getX(i));
78	                    writeDouble(out, scratch, line.getY(i));
79	                    if (line.hasZ()) {
80	                        writeDouble(out, scratch, line.getZ(i));
81	                    }
82	                }
83	                return null;
84	            }
85	
86	            @Override
87	            public Void visit(Polygon polygon) {
88	                writeInt(out, scratch, polygon.hasZ() ? 1003 : 3);
89	                if (polygon.isEmpty()) {
90	                    writeInt(out, scratch, 0);
91	                    return null;
92	                }
93	                writeInt(out, scratch, polygon.getNumberOfHoles() + 1);
94	                visitLinearRing(polygon.getPolygon());
95	                for (int i = 0; i < polygon.getNumberOfHoles(); i++) {
96	                    visitLinearRing(polygon.getHole(i));
97	                }
98	                return null;
99	            }
100	
101	            @Override
102	            public Void visit(MultiPoint multiPoint) {
103	                writeInt(out, scratch, multiPoint.hasZ() ? 1004 : 4);
104	                writeInt(out, scratch, multiPoint.size());
105	                for (Point point : multiPoint) {
106	                    toWKB(point, out, scratch);
107	                }
108	                return null;
109	            }
110	
111	            @Override
112	            public Void visit(MultiLine multiLine) {
113	                writeInt(out, scratch, multiLine.hasZ() ? 1005 : 5);
114	                writeInt(out, scratch, multiLine.size());
115	                for (Line line : multiLine) {
116	                    toWKB(line, out, scratch);
117	                }
118	                return null;
119	            }
120	
121	            @Override
122	            public Void visit(MultiPolygon multiPolygon) {
123	                writeInt(out, scratch, multiPolygon.hasZ() ? 1006 : 6);
124	                writeInt(out, scratch, multiPolygon.size());
125	                for (Polygon polygon : multiPolygon) {
126	                    toWKB(polygon, out, scratch);
127	                }
128	                return null;
129	            }
130	
131	            @Override
132	            public Void visit(GeometryCollection<?> collection) {
133	                writeInt(out, scratch, collection.hasZ() ? 1007 : 7);
134	                writeInt(out, scratch, collection.size());
135	                for (Geometry geometry : collection) {
136	                    toWKB(geometry, out, scratch);
137	                }
138	                return null;
139	            }
140	
141	            @Override
142	            public Void visit(Circle circle) {
143	                if (circle.isEmpty()) {
144	                    throw new IllegalArgumentException("Empty " + circle.type() + " cannot be represented in WKB");
145	                }
146	                writeInt(out, scratch, circle.hasZ() ? 1017 : 17);
147	                writeDouble(out, scratch, circle.getX());
148	                writeDouble(out, scratch, circle.getY());
149	                if (circle.hasZ()) {
150	                    writeDouble(out, scratch, circle.getZ());
151	                }
152	                writeDouble(out, scratch, circle.getRadiusMeters());
153	                return null;
154	            }
155	
156	            @Override
157	            public Void visit(Rectangle rectangle) {
158	                if (rectangle.isEmpty()) {
159	                    throw new IllegalArgumentException("Empty " + rectangle.type() + " cannot be represented in WKB");
160	                }
161	                writeInt(out, scratch, rectangle.hasZ() ? 1018 : 18);
162	                // minX, maxX, maxY, minY
163	                writeDouble(out, scratch, rectangle.getMinX());
164	                writeDouble(out, scratch, rectangle.getMaxX());
165	                writeDouble(out, scratch, rectangle.getMaxY());
166	                writeDouble(out, scratch, rectangle.getMinY());
167	                if (rectangle.hasZ()) {
168	                    writeDouble(out, scratch, rectangle.getMinZ());
169	                    writeDouble(out, scratch, rectangle.getMaxZ());
170	                }
171	                return null;
172	            }
173	
174	            @Override
175	            public Void visit(LinearRing ring) {
176	                throw new IllegalArgumentException("Linear ring is not supported by WKB");
177	            }
178	
179	            private void visitLinearRing(LinearRing ring) {
180	                writeInt(out, scratch, ring.length());
181	                for (int i = 0; i < ring.length(); i++) {
182	                    writeDouble(out, scratch, ring.getX(i));
183	                    writeDouble(out, scratch, ring.getY(i));
184	                    if (ring.hasZ()) {
185	                        writeDouble(out, scratch, ring.getZ(i));
186	                    }
187	                }
188	            }
189	        });
190	    }
191	
192	    private static void writeInt(ByteArrayOutputStream out, ByteBuffer scratch, int i) {
193	        scratch.clear();
194	        scratch.putInt(i);
195	        out.write(scratch.array(), 0, 4);
196	    }
197	
198	    private static void writeDouble(ByteArrayOutputStream out, ByteBuffer scratch, double d) {
199	        scratch.clear();
200	        scratch.putDouble(d);
201	        out.write(scratch.array(), 0, 8);
202	    }
203	
204	    /**
205	     * Reads a {@link Geometry} from the given WKB byte array.
206	     */
207	    public static Geometry fromWKB(GeometryValidator validator, boolean coerce, byte[] wkb) {
208	        return fromWKB(validator, coerce, wkb, 0, wkb.length);
209	    }
210	
211	    /**
212	     * Reads a {@link Geometry} from the given WKB byte array with offset.
213	     */
214	    public static Geometry fromWKB(GeometryValidator validator, boolean coerce, byte[] wkb, int offset, int length) {
215	        final ByteBuffer byteBuffer = ByteBuffer.wrap(wkb, offset, length);
216	        final Geometry geometry = parseGeometry(byteBuffer, coerce);
217	        validator.validate(geometry);
218	        return geometry;
219	    }
220	
221	    private static Geometry parseGeometry(ByteBuffer byteBuffer, boolean coerce) {
222	        byteBuffer.order(byteBuffer.get() == 0 ? ByteOrder.BIG_ENDIAN : ByteOrder.LITTLE_ENDIAN);
223	        final int type = byteBuffer.getInt();
224	        return switch (type) {
225	            case 1 -> parsePoint(byteBuffer, false);
226	            case 1001 -> parsePoint(byteBuffer, true);
227	            case 2 -> parseLine(byteBuffer, false);
228	            case 1002 -> parseLine(byteBuffer, true);
229	            case 3 -> parsePolygon(byteBuffer, false, coerce);
230	            case 1003 -> parsePolygon(byteBuffer, true, coerce);
231	            case 4, 1004 -> parseMultiPoint(byteBuffer);
232	            case 5, 1005 -> parseMultiLine(byteBuffer);
233	            case 6, 1006 -> parseMultiPolygon(byteBuffer, coerce);
234	            case 7, 1007 -> parseGeometryCollection(byteBuffer, coerce);
235	            case 17 -> parseCircle(byteBuffer, false);
236	            case 1017 -> parseCircle(byteBuffer, true);
237	            case 18 -> parseBBox(byteBuffer, false);
238	            case 1018 -> parseBBox(byteBuffer, true);
239	            default -> throw new IllegalArgumentException("Unknown geometry type: " + type);
240	        };
241	    }
242	
243	    private static Point parsePoint(ByteBuffer byteBuffer, boolean hasZ) {
244	        if (hasZ) {
245	            return new Point(byteBuffer.getDouble(), byteBuffer.getDouble(), byteBuffer.getDouble());
246	        } else {
247	            return new Point(byteBuffer.getDouble(), byteBuffer.getDouble());
248	        }
249	    }
250	
251	    private static Line parseLine(ByteBuffer byteBuffer, boolean hasZ) {
252	        final int length = byteBuffer.getInt();
253	        if (length == 0) {
254	            return Line.EMPTY;
255	        }
256	        final double[] lats = new double[length];
257	        final double[] lons = new double[length];
258	        final double[] alts = hasZ ? new double[length] : null;
259	        for (int i = 0; i < length; i++) {
260	            lons[i] = byteBuffer.getDouble();
261	            lats[i] = byteBuffer.getDouble();
262	            if (hasZ) {
263	                alts[i] = byteBuffer.getDouble();
264	            }
265	        }
266	        if (hasZ) {
267	            return new Line(lons, lats, alts);
268	        } else {
269	            return new Line(lons, lats);
270	        }
271	    }
272	
273	    private static Polygon parsePolygon(ByteBuffer byteBuffer, boolean hasZ, boolean coerce) {
274	        final int rings = byteBuffer.getInt();
275	        if (rings == 0) {
276	            return Polygon.EMPTY;
277	        }
278	        final LinearRing shell = parseLinearRing(byteBuffer, hasZ, coerce);
279	        final List<LinearRing> holes = new ArrayList<>();
280	        for (int i = 1; i < rings; i++) {
281	            holes.add(parseLinearRing(byteBuffer, hasZ, coerce));
282	        }
283	        if (holes.isEmpty()) {
284	            return new Polygon(shell);
285	        } else {
286	            return new Polygon(shell, Collections.unmodifiableList(holes));
287	        }
288	    }
289	
290	    private static MultiPoint parseMultiPoint(ByteBuffer byteBuffer) {
291	        final int numPoints = byteBuffer.getInt();
292	        if (numPoints == 0) {
293	            return MultiPoint.EMPTY;
294	        }
295	        final List<Point> points = new ArrayList<>(numPoints);
296	        for (int i = 0; i < numPoints; i++) {
297	            final Geometry geometry = parseGeometry(byteBuffer, false);
298	            if (geometry instanceof Point p) {
299	                points.add(p);
300	            } else {
301	                throw new IllegalArgumentException("Expected a " + ShapeType.POINT + ", got [" + geometry.type() + "]");
302	            }
303	
304	        }
305	        return new MultiPoint(Collections.unmodifiableList(points));
306	    }
307	
308	    private static MultiLine parseMultiLine(ByteBuffer byteBuffer) {
309	        final int numLines = byteBuffer.getInt();
310	        if (numLines == 0) {
311	            return MultiLine.EMPTY;
312	        }
313	        final List<Line> lines = new ArrayList<>(numLines);
314	        for (int i = 0; i < numLines; i++) {
315	            final Geometry geometry = parseGeometry(byteBuffer, false);
316	            if (geometry instanceof Line l) {
317	                lines.add(l);
318	            } else {
319	                throw new IllegalArgumentException("Expected a " + ShapeType.LINESTRING + ", got [" + geometry.type() + "]");
320	            }
321	        }
322	        return new MultiLine(Collections.unmodifiableList(lines));
323	    }
324	
325	    private static MultiPolygon parseMultiPolygon(ByteBuffer byteBuffer, boolean coerce) {
326	        final int numPolygons = byteBuffer.getInt();
327	        if (numPolygons == 0) {
328	            return MultiPolygon.EMPTY;
329	        }
330	        final List<Polygon> polygons = new ArrayList<>(numPolygons);
331	        for (int i = 0; i < numPolygons; i++) {
332	            final Geometry geometry = parseGeometry(byteBuffer, coerce);
333	            if (geometry instanceof Polygon p) {
334	                polygons.add(p);
335	            } else {
336	                throw new IllegalArgumentException("Expected a " + ShapeType.POLYGON + ", got [" + geometry.type() + "]");
337	            }
338	
339	        }
340	        return new MultiPolygon(Collections.unmodifiableList(polygons));
341	    }
342	
343	    private static GeometryCollection<Geometry> parseGeometryCollection(ByteBuffer byteBuffer, boolean coerce) {
344	        final int numShapes = byteBuffer.getInt();
345	        if (numShapes == 0) {
346	            return GeometryCollection.EMPTY;
347	        }
348	        final List<Geometry> shapes = new ArrayList<>(numShapes);
349	        for (int i = 0; i < numShapes; i++) {
350	            shapes.add(parseGeometry(byteBuffer, coerce));
351	        }
352	        return new GeometryCollection<>(shapes);
353	    }
354	
355	    private static LinearRing parseLinearRing(ByteBuffer byteBuffer, boolean hasZ, boolean coerce) {
356	        final int length = byteBuffer.getInt();
357	        if (length == 0) {
358	            return LinearRing.EMPTY;
359	        }
360	        double[] lons = new double[length];
361	        double[] lats = new double[length];
362	        double[] alts = hasZ ? new double[length] : null;
363	        for (int i = 0; i < length; i++) {
364	            lons[i] = byteBuffer.getDouble();
365	            lats[i] = byteBuffer.getDouble();
366	            if (hasZ) {
367	                alts[i] = byteBuffer.getDouble();
368	            }
369	        }
370	        if (linearRingNeedsCoerced(lats, lons, alts, coerce)) {
371	            lons = coerce(lons);
372	            lats = coerce(lats);
373	            if (hasZ) {
374	                alts = coerce(alts);
375	            }
376	        }
377	        if (hasZ) {
378	            return new LinearRing(lons, lats, alts);
379	        } else {
380	            return new LinearRing(lons, lats);
381	        }
382	    }
383	
384	    private static boolean linearRingNeedsCoerced(double[] lons, double[] lats, double[] alts, boolean coerce) {
385	        assert lats.length == lons.length && (alts == null || alts.length == lats.length);
386	        assert lats.length > 0;
387	        if (coerce == false) {
388	            return false;
389	        }
390	        final int last = lons.length - 1;
391	        return lons[0] != lons[last] || lats[0] != lats[last] || (alts != null && alts[0] != alts[last]);
392	    }
393	
394	    private static double[] coerce(double[] array) {
395	        double[] copy = new double[array.length + 1];
396	        System.arraycopy(array, 0, copy, 0, array.length);
397	        copy[array.length] = copy[0];
398	        return copy;
399	    }
400	
401	    private static Rectangle parseBBox(ByteBuffer byteBuffer, boolean hasZ) {
402	        if (hasZ) {
403	            return new Rectangle(
404	                byteBuffer.getDouble(),
405	                byteBuffer.getDouble(),
406	                byteBuffer.getDouble(),
407	                byteBuffer.getDouble(),
408	                byteBuffer.getDouble(),
409	                byteBuffer.getDouble()
410	            );
411	        } else {
412	            return new Rectangle(byteBuffer.getDouble(), byteBuffer.getDouble(), byteBuffer.getDouble(), byteBuffer.getDouble());
413	        }
414	    }
415	
416	    private static Circle parseCircle(ByteBuffer byteBuffer, boolean hasZ) {
417	        if (hasZ) {
418	            return new Circle(byteBuffer.getDouble(), byteBuffer.getDouble(), byteBuffer.getDouble(), byteBuffer.getDouble());
419	        } else {
420	            return new Circle(byteBuffer.getDouble(), byteBuffer.getDouble(), byteBuffer.getDouble());
421	        }
422	    }
423	}
