10	package org.elasticsearch.cli;
11	
12	import joptsimple.NonOptionArgumentSpec;
13	import joptsimple.OptionSet;
14	import joptsimple.OptionSpec;
15	import joptsimple.util.KeyValuePair;
16	
17	import org.elasticsearch.cli.terminal.Terminal;
18	import org.elasticsearch.core.IOUtils;
19	
20	import java.io.IOException;
21	import java.util.ArrayList;
22	import java.util.LinkedHashMap;
23	import java.util.List;
24	import java.util.Map;
25	import java.util.function.Consumer;
26	
27	/**
28	 * A cli tool which is made up of multiple subcommands.
29	 */
30	public class MultiCommand extends Command {
31	
32	    protected final Map<String, Command> subcommands = new LinkedHashMap<>();
33	
34	    private final NonOptionArgumentSpec<String> arguments = parser.nonOptions("command");
35	    private final OptionSpec<KeyValuePair> settingOption;
36	
37	    /**
38	     * Construct the multi-command with the specified command description and runnable to execute before main is invoked.
39	     *  @param description the multi-command description
40	     *
41	     */
42	    public MultiCommand(final String description) {
43	        super(description);
44	        this.settingOption = parser.accepts("E", "Configure a setting").withRequiredArg().ofType(KeyValuePair.class);
45	        parser.posixlyCorrect(true);
46	    }
47	
48	    @Override
49	    protected void printAdditionalHelp(Terminal terminal) {
50	        printSubCommandList(terminal::println);
51	    }
52	
53	    @Override
54	    protected void printUserException(Terminal terminal, UserException e) {
55	        super.printUserException(terminal, e);
56	        if (e instanceof MissingCommandException) {
57	            terminal.errorPrintln("");
58	            printSubCommandList(terminal::errorPrintln);
59	        }
60	    }
61	
62	    private void printSubCommandList(Consumer<String> println) {
63	        if (subcommands.isEmpty()) {
64	            throw new IllegalStateException("No subcommands configured");
65	        }
66	        println.accept("Commands");
67	        println.accept("--------");
68	        for (Map.Entry<String, Command> subcommand : subcommands.entrySet()) {
69	            println.accept(subcommand.getKey() + " - " + subcommand.getValue().description);
70	        }
71	        println.accept("");
72	    }
73	
74	    @Override
75	    protected void execute(Terminal terminal, OptionSet options, ProcessInfo processInfo) throws Exception {
76	        if (subcommands.isEmpty()) {
77	            throw new IllegalStateException("No subcommands configured");
78	        }
79	
80	        // .values(...) returns an unmodifiable list
81	        final List<String> args = new ArrayList<>(arguments.values(options));
82	        if (args.isEmpty()) {
83	            throw new MissingCommandException();
84	        }
85	
86	        String subcommandName = args.remove(0);
87	        Command subcommand = subcommands.get(subcommandName);
88	        if (subcommand == null) {
89	            throw new UserException(ExitCodes.USAGE, "Unknown command [" + subcommandName + "]");
90	        }
91	
92	        for (final KeyValuePair pair : this.settingOption.values(options)) {
93	            args.add("-E" + pair);
94	        }
95	
96	        subcommand.mainWithoutErrorHandling(args.toArray(new String[0]), terminal, processInfo);
97	    }
98	
99	    @Override
100	    public void close() throws IOException {
101	        IOUtils.close(subcommands.values());
102	    }
103	
104	    static final class MissingCommandException extends UserException {
105	        MissingCommandException() {
106	            super(ExitCodes.USAGE, "Missing required command");
107	        }
108	    }
