81	    /** Returns true if this is a valid H3 index */
82	    public static boolean h3IsValid(long h3) {
83	        if (H3Index.H3_get_high_bit(h3) != 0) {
84	            return false;
85	        }
86	
87	        if (H3Index.H3_get_mode(h3) != Constants.H3_CELL_MODE) {
88	            return false;
89	        }
90	
91	        if (H3Index.H3_get_reserved_bits(h3) != 0) {
92	            return false;
93	        }
94	
95	        int baseCell = H3Index.H3_get_base_cell(h3);
96	        if (baseCell < 0 || baseCell >= Constants.NUM_BASE_CELLS) {  // LCOV_EXCL_BR_LINE
97	            // Base cells less than zero can not be represented in an index
98	            return false;
99	        }
100	
101	        int res = H3Index.H3_get_resolution(h3);
102	        if (res < 0 || res > MAX_H3_RES) {  // LCOV_EXCL_BR_LINE
103	            // Resolutions less than zero can not be represented in an index
104	            return false;
105	        }
106	
107	        boolean foundFirstNonZeroDigit = false;
108	        for (int r = 1; r <= res; r++) {
109	            int digit = H3Index.H3_get_index_digit(h3, r);
110	
111	            if (foundFirstNonZeroDigit == false && digit != CoordIJK.Direction.CENTER_DIGIT.digit()) {
112	                foundFirstNonZeroDigit = true;
113	                if (BaseCells.isBaseCellPentagon(baseCell) && digit == CoordIJK.Direction.K_AXES_DIGIT.digit()) {
114	                    return false;
115	                }
116	            }
117	
118	            if (digit < CoordIJK.Direction.CENTER_DIGIT.digit() || digit >= CoordIJK.Direction.NUM_DIGITS.digit()) {
119	                return false;
120	            }
121	        }
122	
123	        for (int r = res + 1; r <= MAX_H3_RES; r++) {
124	            int digit = H3Index.H3_get_index_digit(h3, r);
125	            if (digit != CoordIJK.Direction.INVALID_DIGIT.digit()) {
126	                return false;
127	            }
128	        }
129	        return true;
130	    }
