258	    /**
259	     * Returns the child cell at the given position
260	     */
261	    public static long childPosToH3(long h3, int childPos) {
262	        final int childrenRes = H3Index.H3_get_resolution(h3) + 1;
263	        if (childrenRes > MAX_H3_RES) {
264	            throw new IllegalArgumentException("Resolution overflow");
265	        }
266	        final long childH = H3Index.H3_set_resolution(h3, childrenRes);
267	        if (childPos == 0) {
268	            return H3Index.H3_set_index_digit(childH, childrenRes, CoordIJK.Direction.CENTER_DIGIT.digit());
269	        }
270	        final boolean isPentagon = isPentagon(h3);
271	        final int maxPos = isPentagon ? 5 : 6;
272	        if (childPos < 0 || childPos > maxPos) {
273	            throw new IllegalArgumentException("invalid child position");
274	        }
275	        if (isPentagon) {
276	            // Pentagon skip digit (position) is the number 1, therefore we add one
277	            // to the current position.
278	            return H3Index.H3_set_index_digit(childH, childrenRes, childPos + 1);
279	        } else {
280	            return H3Index.H3_set_index_digit(childH, childrenRes, childPos);
281	        }
282	    }
