299	        final boolean isPentagon = isPentagon(h3);
300	        final long[] noChildren = new long[isPentagon ? 5 : 6];
301	        for (int i = 0; i < noChildren.length; i++) {
302	            noChildren[i] = noChildIntersectingPosToH3(h3, i);
303	        }
304	        return noChildren;
305	    }
