315	    /**
316	     * Returns the no child intersecting cell at the given position
317	     */
318	    public static long noChildIntersectingPosToH3(long h3, int childPos) {
319	        final int childrenRes = H3Index.H3_get_resolution(h3) + 1;
320	        if (childrenRes > MAX_H3_RES) {
321	            throw new IllegalArgumentException("Resolution overflow");
322	        }
323	        final boolean isPentagon = isPentagon(h3);
324	        final int maxPos = isPentagon ? 4 : 5;
325	        if (childPos < 0 || childPos > maxPos) {
326	            throw new IllegalArgumentException("invalid child position");
327	        }
328	        final long childH = H3Index.H3_set_resolution(h3, childrenRes);
329	        if (isPentagon) {
330	            // Pentagon skip digit (position) is the number 1, therefore we add one
331	            // for the skip digit and one for the 0 (center) digit.
332	            final long child = H3Index.H3_set_index_digit(childH, childrenRes, childPos + 2);
333	            return HexRing.h3NeighborInDirection(child, PEN_INTERSECTING_CHILDREN_DIRECTIONS[childPos]);
334	        } else {
335	            // we add one for the 0 (center) digit.
336	            final long child = H3Index.H3_set_index_digit(childH, childrenRes, childPos + 1);
337	            return HexRing.h3NeighborInDirection(child, HEX_INTERSECTING_CHILDREN_DIRECTIONS[childPos]);
338	        }
339	    }
