442	    /**
443	     * h3ToChildrenSize returns the exact number of children for a cell at a
444	     * given child resolution.
445	     *
446	     * @param h3         H3Index to find the number of children of
447	     * @param childRes  The child resolution you're interested in
448	     *
449	     * @return long      Exact number of children (handles hexagons and pentagons
450	     *                  correctly)
451	     */
452	    public static long h3ToChildrenSize(long h3, int childRes) {
453	        final int parentRes = H3Index.H3_get_resolution(h3);
454	        if (childRes <= parentRes || childRes > MAX_H3_RES) {
455	            throw new IllegalArgumentException("Invalid child resolution [" + childRes + "]");
456	        }
457	        final int n = childRes - parentRes;
458	        if (H3Index.H3_is_pentagon(h3)) {
459	            return (1L + 5L * (_ipow(7, n) - 1L) / 6L);
460	        } else {
461	            return _ipow(7, n);
462	        }
463	    }
